// Invented fixture only. No network request, hosted Actor or Telegram delivery.
const sample = [
  {
    "schema_version": "1.0",
    "message_count": 2,
    "messages": [
      {
        "index": 1,
        "text": "Hello 😀 world",
        "entities": [
          {
            "type": "bold",
            "offset": 9,
            "length": 5
          }
        ]
      },
      {
        "index": 2,
        "text": "Second synthetic part.",
        "entities": []
      }
    ],
    "warnings": []
  }
];
return sample.map(json => ({json}));

const rows = $input.all().map(item => item.json);
if (rows.length !== 1) throw new Error('Expected one result; inspect the existing Apify run before retrying.');
const result = rows[0];
if (result.schema_version !== '1.0' || !Array.isArray(result.messages) || result.messages.length < 1 || result.messages.length > 20 || result.message_count !== result.messages.length) throw new Error('Unexpected result schema.');
return result.messages.map((m, i) => {
  if (m.index !== i + 1 || typeof m.text !== 'string' || !m.text.trim() || m.text.length > 4096 || !Array.isArray(m.entities)) throw new Error('Invalid message or sequence.');
  for (const e of m.entities) {
    if (!Number.isInteger(e.offset) || !Number.isInteger(e.length) || e.offset < 0 || e.length < 1 || e.offset + e.length > m.text.length) throw new Error('Invalid UTF-16 entity bounds.');
  }
  return {json: {sequence: m.index, text: m.text, entities: m.entities, warnings: result.warnings || []}};
});
